def transform(grid):
    panels = [[row[s:s+4] for row in grid] for s in (0, 5, 10, 15)]
    # At each coordinate the output color is determined by all four layers.
    # The observed rule is a fixed ordered overlay: single-layer pixels keep
    # that layer's color; overlaps encode as 9 except 8+4 -> 4.
    out = [[0] * 4 for _ in range(4)]
    for r in range(4):
        for c in range(4):
            vals = [p[r][c] for p in panels if p[r][c] != 0]
            if len(vals) == 0:
                out[r][c] = 0
            elif len(vals) == 1:
                out[r][c] = vals[0]
            elif 8 in vals and 4 in vals and len(vals) == 2:
                out[r][c] = 4
            elif vals == [8, 5]:
                out[r][c] = 8
            elif vals == [5, 4]:
                out[r][c] = 5
            else:
                out[r][c] = 9
    return out
